private void ExportDrivingSummaryToHTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    string strHead = DrivingSummaryHeaderToHTML();
    string strBody = DrivingSummaryBodyToHTML();
    string strDetail = "<table cellpadding='4' cellspacing='0' style='border-collapse:collapse; font-family:Times New Roman; font-size:12pt;'>"
        + strHead + strBody + "</table>";

    string strFileContent = GetModuleMarkHTMLTemplate(DRIVING_SUMMARY_HTML_TEMPLATE);
    strFileContent = strFileContent.Replace("{DETAIL}", strDetail);

    string strClassName = uClass.ClassName == null ? "" : uClass.ClassName.ToString().Trim();
    string strCourseName = uClass.CourseName == null ? "" : uClass.CourseName.ToString().Trim();
    strFileContent = strFileContent.Replace("{CLASSNAME}", strClassName);
    strFileContent = strFileContent.Replace("{COURSENAME}", strCourseName);

    string strClassCode = uClass.ClassIDEditValue.ToString();
    foreach (char chrInvalid in System.IO.Path.GetInvalidFileNameChars())
        strClassCode = strClassCode.Replace(chrInvalid, '_');

    string strFileNameAs = String.Format("{0}_{1}_{2}",
        strClassCode,
        DateTime.Now.ToString("HHmmss"),
        DRIVING_SUMMARY_HTML_TEMPLATE);
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

private string DrivingSummaryHeaderToHTML()
{
    string strHeaderStyle = " style='" + MODULE_MARK_TD_BORDER + "background-color:#cccccc;font-weight:bold;text-align:center;'";

    string strRow = "<tr>";
    strRow += "<td" + strHeaderStyle + ">Số TT</td>";
    strRow += "<td class='cell-name'" + strHeaderStyle + "white-space:nowrap;'>Họ và tên học sinh</td>";
    strRow += "<td" + strHeaderStyle + ">Ngày sinh</td>";

    foreach (DataRow drwSubject in dtbClassSubject.Rows)
    {
        strRow += "<td" + strHeaderStyle + ">" + drwSubject["SubjectName"].ToString() + "</td>";
    }

    strRow += "<td" + strHeaderStyle + ">Kết quả</td>";
    strRow += "<td" + strHeaderStyle + ">Khóa học</td>";
    strRow += "<td" + strHeaderStyle + ">Ghi chú</td>";
    strRow += "</tr>\r\n";

    return strRow;
}

private string DrivingSummaryBodyToHTML()
{
    StringBuilder sb = new StringBuilder();
    int intSTT = 0;
    string strCellStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:center;'";
    string strNameStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:left;white-space:nowrap;'";
    string strNoteStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:left;'";
    string strCourseName = uClass.CourseName == null ? "&nbsp;" : uClass.CourseName.ToString().Trim();
    if (strCourseName == "")
        strCourseName = "&nbsp;";

    for (int i = 0; i < gvData.RowCount; i++)
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td" + strCellStyle + ">" + intSTT.ToString() + "</td>");

        string strFullName = (drw["StudentFirstName"].ToString() + " " + drw["StudentLastName"].ToString()).Trim();
        sb.Append("<td class='cell-name'" + strNameStyle + ">" + strFullName + "</td>");

        string strBirthDate = "&nbsp;";
        if (drw.Table.Columns.Contains("BirthDateText") && drw["BirthDateText"] != DBNull.Value && drw["BirthDateText"].ToString().Trim() != "")
            strBirthDate = drw["BirthDateText"].ToString().Trim();
        sb.Append("<td" + strCellStyle + ">" + strBirthDate + "</td>");

        for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
        {
            int intIndex = j + 1;
            string strField = "FinalSummary_" + intIndex.ToString();
            object objValue = drw[strField];
