            string strMarkStyle = strCellStyle;

            if (ModuleMarkIsFailed(objValue))
                strMarkStyle = " style='" + MODULE_MARK_TD_BORDER + "background-color:Yellow;text-align:center;'";

            sb.Append("<td" + strMarkStyle + ">" + strValue + "</td>");
        }

        string strLearningLevel = "&nbsp;";
        if (drw.Table.Columns.Contains("LearningLevel") && drw["LearningLevel"] != DBNull.Value && drw["LearningLevel"].ToString().Trim() != "")
            strLearningLevel = drw["LearningLevel"].ToString().Trim();
        sb.Append("<td" + strCellStyle + ">" + strLearningLevel + "</td>");

        sb.Append("<td" + strCellStyle + ">" + strCourseName + "</td>");

        string strDescription = "&nbsp;";
        if (drw.Table.Columns.Contains("Description") && drw["Description"] != DBNull.Value && drw["Description"].ToString().Trim() != "")
            strDescription = drw["Description"].ToString().Trim();
        sb.Append("<td" + strNoteStyle + ">" + strDescription + "</td>");
        sb.Append("</tr>\r\n");
