    int intGroupStart = DrivingSummaryFindDrivingGroupStartIndex();

    if (intGroupStart < 0)
    {
        string strRow = "<tr>";
        strRow += "<td" + strHeaderStyle + ">STT</td>";
        strRow += "<td class='cell-name'" + strHeaderStyle + "white-space:nowrap;'>Họ và tên học sinh</td>";
        strRow += "<td" + strHeaderStyle + ">Ngày sinh</td>";

        foreach (DataRow drwSubject in dtbClassSubject.Rows)
        {
            strRow += "<td" + strHeaderStyle + ">" + drwSubject["SubjectName"].ToString() + "</td>";
        }

        strRow += "<td" + strHeaderStyle + ">Kết quả</td>";
        strRow += "<td" + strHeaderStyle + ">Khóa học</td>";
        strRow += "<td" + strHeaderStyle + ">Ghi chú</td>";
        strRow += "</tr>\r\n";

        return strRow;
    }

    StringBuilder sb = new StringBuilder();

    sb.Append("<tr>");
    sb.Append("<td rowspan='2'" + strHeaderStyle + ">STT</td>");
    sb.Append("<td rowspan='2' class='cell-name'" + strHeaderStyle + "white-space:nowrap;'>Họ và tên học sinh</td>");
    sb.Append("<td rowspan='2'" + strHeaderStyle + ">Ngày sinh</td>");

    for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
    {
        if (j == intGroupStart)
        {
            sb.Append("<td colspan='3'" + strHeaderStyle + ">" + DRIVING_PRACTICE_GROUP_TITLE + "</td>");
            j += DRIVING_PRACTICE_GROUP_CODES.Length - 1;
        }
        else
        {
            sb.Append("<td rowspan='2'" + strHeaderStyle + ">" + dtbClassSubject.Rows[j]["SubjectName"].ToString() + "</td>");
        }
    }

    sb.Append("<td rowspan='2'" + strHeaderStyle + ">Kết quả</td>");
    sb.Append("<td rowspan='2'" + strHeaderStyle + ">Khóa học</td>");
    sb.Append("<td rowspan='2'" + strHeaderStyle + ">Ghi chú</td>");
    sb.Append("</tr>\r\n");

    sb.Append("<tr>");
    for (int k = 0; k < DRIVING_PRACTICE_SUB_HEADERS.Length; k++)
        sb.Append("<td" + strHeaderStyle + ">" + DRIVING_PRACTICE_SUB_HEADERS[k] + "</td>");
    sb.Append("</tr>\r\n");

    return sb.ToString();
}

private string DrivingSummaryGetSubjectShortName(DataRow drwSubject)
{
    if (drwSubject.Table.Columns.Contains("SubjectShortName")
        && drwSubject["SubjectShortName"] != DBNull.Value
        && drwSubject["SubjectShortName"].ToString().Trim() != "")
        return drwSubject["SubjectShortName"].ToString().Trim();

    return "";
}

private int DrivingSummaryFindDrivingGroupStartIndex()
{
    for (int i = 0; i <= dtbClassSubject.Rows.Count - DRIVING_PRACTICE_GROUP_CODES.Length; i++)
    {
        bool bolMatch = true;
        for (int k = 0; k < DRIVING_PRACTICE_GROUP_CODES.Length; k++)
        {
            if (DrivingSummaryGetSubjectShortName(dtbClassSubject.Rows[i + k]) != DRIVING_PRACTICE_GROUP_CODES[k])
            {
                bolMatch = false;
                break;
            }
        }

        if (bolMatch)
            return i;
    }

    return -1;
}

