private bool DrivingSummaryIsDrivingPracticeSubjectIndex(int intSubjectIndex)
{
    int[] arrDrivingIndexes = DrivingSummaryGetDrivingGroupIndexes();
    if (arrDrivingIndexes == null)
        return false;

    for (int i = 0; i < arrDrivingIndexes.Length; i++)
    {
        if (arrDrivingIndexes[i] == intSubjectIndex)
            return true;
    }

    return false;
}

private int[] DrivingSummaryGetDrivingGroupIndexes()
{
    List<int> lstIndexes = new List<int>();

    for (int k = 0; k < DRIVING_PRACTICE_GROUP_CODES.Length; k++)
    {
        int intFound = -1;
        for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
        {
            string strShortName = DrivingSummaryGetSubjectShortName(dtbClassSubject.Rows[j]);
            string strSubjectName = dtbClassSubject.Rows[j]["SubjectName"].ToString().Trim();

            if (strShortName == DRIVING_PRACTICE_GROUP_CODES[k]
                || strSubjectName == DRIVING_PRACTICE_SUB_HEADERS[k])
            {
                intFound = j;
                break;
            }
        }

        if (intFound < 0)
            return null;

        lstIndexes.Add(intFound);
    }

    return lstIndexes.ToArray();
}

private int[] DrivingSummaryGetExportSubjectIndexes()
{
    int[] arrDrivingIndexes = DrivingSummaryGetDrivingGroupIndexes();
    if (arrDrivingIndexes == null)
    {
        int[] arrAll = new int[dtbClassSubject.Rows.Count];
        for (int i = 0; i < arrAll.Length; i++)
            arrAll[i] = i;
        return arrAll;
    }

    List<int> lstResult = new List<int>();
    bool[] arrUsed = new bool[dtbClassSubject.Rows.Count];
    for (int i = 0; i < arrDrivingIndexes.Length; i++)
        arrUsed[arrDrivingIndexes[i]] = true;

    for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
    {
        if (!arrUsed[j])
            lstResult.Add(j);
    }

    for (int i = 0; i < arrDrivingIndexes.Length; i++)
        lstResult.Add(arrDrivingIndexes[i]);

    return lstResult.ToArray();
}

